     //Do Something
  }
}

//Log class field
public void Stop()
{
  Log.WriteLine(5, "Stopping Plugin");

  //Do some cleanup

  //Set private fields.  
  //Properties to get these values are used in the Extended Service 
  _Running = false;
  _Stopped = true;
}
